//! ✒️ Writer-owned strings and fixed persisted document handle use two handcrafted entities.
use super::WriterSnapshot;
use semio_framework_os_kernel::{ArtifactSqliteSnapshot,sqlite_snapshot::{SqliteDatabase,SqliteSnapshotControl,SqliteSnapshotPhase,SnapshotEncoding,validate_sqlite_database_schema,artifact::{Projection,Cell,NativeEncodingBound}}};
impl ArtifactSqliteSnapshot for WriterSnapshot{
 const SQLITE_SCHEMA:&'static str=include_str!("🗄️.sql");
 fn preflight_sqlite_snapshot_encoding(&self,_encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<(),String>{let mut bound=NativeEncodingBound::new(control)?;bound.add(8192)?;for text in[&self.schema,&self.id,&self.language_id,&self.uri,&self.text,&self.document.child_id,&self.document.target.artifact_id,&self.document.target.dialect.artifact_kind,&self.document.target.dialect.standard,&self.document.target.dialect.subset]{bound.repeated(text.len(),6)?;}bound.finish()}
 fn to_sqlite_database(&self,control:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase,String>{let mut p=Projection::new(Self::SQLITE_SCHEMA,control)?;p.check_rows(2)?;p.insert_key("writer_document",1,&[Cell::Text(&self.schema),Cell::Text(&self.id),Cell::Text(&self.language_id),Cell::Text(&self.uri),Cell::Text(&self.text)])?;let child=&self.document;p.insert_key("writer_document_child",1,&[Cell::Integer(1),Cell::Text(&child.child_id),Cell::Text(&child.target.artifact_id),Cell::Text(&child.target.dialect.artifact_kind),Cell::Text(&child.target.dialect.standard),Cell::Text(&child.target.dialect.subset)])?;p.finish()}
 fn from_sqlite_database(database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->Result<Self,String>{control.check_database(database,SqliteSnapshotPhase::ReconstructSnapshot)?;validate_sqlite_database_schema(database,Self::SQLITE_SCHEMA,control.limits()).map_err(|error|error.to_string())?;if database.tables.len()!=2{return Err("Writer requires exactly its two owned tables".into())}let document=database.table("writer_document")?.single_row()?;let child=database.table("writer_document_child")?.single_row()?;if document.rowid!=1||document.integer(0)?!=1||document.values.len()!=6||child.rowid!=1||child.integer(0)?!=1||child.integer(1)?!=1||child.values.len()!=7{return Err("Writer fixed ownership differs".into())}for(row,indices)in[(document,&[1usize,2,3,4,5][..]),(child,&[2usize,3,4,5,6][..])]{for&index in indices{if row.text(index)?.len()>65536{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,0,2)?;}}}let result=Self{schema:document.text(1)?.into(),id:document.text(2)?.into(),language_id:document.text(3)?.into(),uri:document.text(4)?.into(),text:document.text(5)?.into(),document:store::ArtifactChild::new(child.text(2)?.into(),store::os_io::ArtifactRef{artifact_id:child.text(3)?.into(),dialect:store::os_io::ArtifactDialect{artifact_kind:child.text(4)?.into(),standard:child.text(5)?.into(),subset:child.text(6)?.into()}})};control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,2,2)?;Ok(result)}
 fn validate_sqlite_snapshot_subset(&self,dialect:&semio_framework_os_kernel::io_schema::ArtifactDialect,database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->semio_framework_os_kernel::io_schema::IoResult<()>{control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,0)?;if dialect.artifact_kind!="s.writer.writer"||dialect.standard!="1"||dialect.subset!="*"{return Err(String::from("Writer does not own this semantic subset").into())}let row=database.table("writer_document")?.single_row()?;if row.rowid!=1||row.integer(0)?!=1||row.text(1)?!=self.schema{return Err(String::from("Writer document identity disagrees with its snapshot").into())}Ok(semio_framework_os_kernel::io_schema::IoOutcome{value:(),diagnostics:Vec::new()})}
}
